/* Sykabelajar stable release loader - generated by build/build.mjs */
(function(){
  if (window.__SYKA_LOADER_STARTED__) return;
  window.__SYKA_LOADER_STARTED__ = true;

  var BASE = "https://cdn.jsdelivr.net/gh/taufx98/sykabelajar-frontend@main/dist";
  var MANIFEST = "https://raw.githubusercontent.com/taufx98/sykabelajar-frontend/refs/heads/main/dist/manifest.json";
  var CACHE_BUSTER = Date.now().toString(36);

  function loadScript(url) {
    return new Promise(function(resolve, reject) {
      var s = document.createElement('script');
      s.src = url;
      s.async = false;
      s.onload = resolve;
      s.onerror = function(){ reject(new Error('Failed to load ' + url)); };
      document.head.appendChild(s);
    });
  }

  function loadCss(url) {
    return new Promise(function(resolve, reject) {
      var l = document.createElement('link');
      l.rel = 'stylesheet';
      l.href = url;
      l.onload = resolve;
      l.onerror = function(){ reject(new Error('Failed to load ' + url)); };
      document.head.appendChild(l);
    });
  }

  function loadModule(url) { return import(url); }

  function applyConfig(manifest){
    window.__SYKA_RELEASE__ = manifest;
    window.SYKA_CONFIG = window.SYKA_CONFIG || {};
    window.SYKA_CONFIG.ASSET_RELEASE = manifest.commit || 'unknown';
    window.SYKA_CONFIG.ASSET_BASE_URL = manifest.base || BASE;
  }

  fetch(MANIFEST + '?cb=' + CACHE_BUSTER, { cache: 'no-store', credentials: 'omit' })
    .then(function(res){
      if (!res.ok) throw new Error('Manifest HTTP ' + res.status);
      return res.json();
    })
    .then(function(manifest){
      if (!manifest || !manifest.app || !manifest.styles || !manifest.vendor) {
        throw new Error('Invalid Sykabelajar release manifest');
      }

      applyConfig(manifest);

      return loadCss((manifest.base || BASE) + '/' + manifest.styles)
        .then(function(){ return loadScript((manifest.base || BASE) + '/' + manifest.vendor); })
        .then(function(){ return loadScript((manifest.base || BASE) + '/' + manifest.app); })
        .then(function(){ if (!manifest.v2 || !manifest.v2.entry) return null; return loadModule((manifest.base || BASE) + '/' + manifest.v2.entry + '?cb=' + CACHE_BUSTER).then(function(v2){ window.SYKA_V2 = v2; return v2; }); });
    })
    .then(function(){
      if (window.SYKA_APP && typeof window.SYKA_APP.init === 'function') {
        return Promise.resolve(window.SYKA_APP.init()).then(function(){ if (window.SYKA_CONFIG && window.SYKA_CONFIG.ENABLE_V2 === true && window.SYKA_V2?.startSykabelajarV2) return window.SYKA_V2.startSykabelajarV2({ mode: 'incremental' }); });
      }
      throw new Error('SYKA_APP.init() tidak ditemukan setelah release bundle dimuat.');
    })
    .catch(function(error){
      console.error('[Sykabelajar] Bootstrap failed:', error);
      document.documentElement.classList.add('syka-boot-error');
      var root = document.getElementById('page-root');
      if (root) {
        root.innerHTML = '<div style="max-width:720px;margin:40px auto;padding:24px;font-family:Inter,system-ui,sans-serif"><h2>Sykabelajar sedang memuat ulang</h2><p>Asset aplikasi belum berhasil dimuat. Silakan refresh halaman.</p><button onclick="location.reload()" style="padding:10px 16px;cursor:pointer">Refresh</button></div>';
      }
    });
})();
